import React from 'react';
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from 'remotion';
import { loadFont } from '@remotion/google-fonts/DMSans';

const { fontFamily } = loadFont();

const palette = {
  textColor: '#FFFFFF',
  scaleColor: '#FFFFFF',
  fulcrumColor: '#FFFFFF',
};

const data = {
  titleLine1: '1 Sugar Cube vs',
  titleLine2: '1 Can of Coke',
  itemA: { value: 4, description: '1 Sugar Cube' },
  itemB: { value: 39, description: '1 Can of Coke' },
};

const AnimatedInteger: React.FC<{ value: number; startFrame: number; durationInFrames: number; }> = ({ value, startFrame, durationInFrames }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const animatedValue = spring({
    frame,
    fps,
    from: 0,
    to: value,
    startFrame,
    durationInFrames,
    config: { damping: 20, stiffness: 100 },
  });

  return <span>{Math.round(animatedValue)}</span>;
};

export const Info_comparison_scale: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Animation Timing (in frames for a ~1.5s total animation at 30fps)
  const TITLE_APPEAR_START = 5;
  const SCALE_APPEAR_START = 10;
  const ITEMS_APPEAR_START = 18;
  const TILT_START = 30;
  const NUMBER_ANIM_START = 32;

  // Geometry
  const boxWidth = 380;
  const boxHeight = 300;
  const beamWidth = 910;
  const beamHeight = 15;
  const fulcrumWidth = 100;
  const fulcrumHeight = 80;
  const scaleCenterY = 1100;

  // --- Animations ---

  const titleProgress = spring({ frame, fps, from: 0, to: 1, startFrame: TITLE_APPEAR_START, durationInFrames: 20 });
  const titleY = interpolate(titleProgress, [0, 1], [-20, 0]);

  const scaleProgress = spring({ frame, fps, from: 0, to: 1, startFrame: SCALE_APPEAR_START, durationInFrames: 25, config: { damping: 30, stiffness: 200 } });
  
  const itemsOpacity = spring({ frame, fps, from: 0, to: 1, startFrame: ITEMS_APPEAR_START, durationInFrames: 20 });
  const itemsY = spring({ frame, fps, from: -400, to: 0, startFrame: ITEMS_APPEAR_START, durationInFrames: 25, config: { damping: 20, stiffness: 150 } });

  // --- Rotation: keep FLAT, then tilt ---
  const rotationFactor = 0.25;
  const delta = data.itemB.value - data.itemA.value;
  const targetRotation = delta * rotationFactor;

  const tiltProgress =
    frame < TILT_START
      ? 0
      : spring({
          frame: frame - TILT_START,
          fps,
          from: 0,
          to: 1,
          durationInFrames: 25,
          config: { damping: 20, stiffness: 120 },
        });

  const scaleRotationDeg = targetRotation * tiltProgress;

  // --- Styles ---

  const titleStyle: React.CSSProperties = {
    fontFamily,
    fontSize: 70,
    fontWeight: '700',
    color: palette.textColor,
    textAlign: 'center',
    position: 'absolute',
    width: '100%',
    left: '50%',
    transform: `translateX(-50%) translateY(${titleY}px)`,
    top: 280,
    opacity: titleProgress,
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    lineHeight: 1.1,
  };

  const fulcrumStyle: React.CSSProperties = {
    position: 'absolute',
    top: scaleCenterY,
    left: '50%',
    width: 0,
    height: 0,
    borderLeft: `${fulcrumWidth / 2}px solid transparent`,
    borderRight: `${fulcrumWidth / 2}px solid transparent`,
    borderBottom: `${fulcrumHeight}px solid ${palette.fulcrumColor}`,
    transform: `translateX(-50%) scale(${scaleProgress})`,
    transformOrigin: 'center top',
    opacity: scaleProgress,
  };

  const rotatingContainerHeight = 400;
  const rotatingContainerStyle: React.CSSProperties = {
    position: 'absolute',
    width: beamWidth,
    height: rotatingContainerHeight,
    left: '50%',
    top: scaleCenterY - rotatingContainerHeight / 2,
    marginLeft: -beamWidth / 2,
    transform: `rotate(${scaleRotationDeg}deg)`,
    transformOrigin: 'center center',
